"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["7725"],{16769(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>i,toc:()=>u,assets:()=>l});var a=JSON.parse('{"id":"qiangguo/normalfall","title":"","description":"As soon as I came online today, I found an unusually large number of posts about the stock market. Yesterday this young lady already wrote Respecting the Market Is the Basic Quality of Every Regulator. Let Us Warmly Applaud the Resounding Slap the Market Has Given to the Stock Market Regulators.\\" The stock market\'s current decline is just normal market law, yet today\'s sudden surge of stock market posts is like the bulls\' last wailing -- an attempt to manufacture public opinion to coerce the government. What are their true intentions? The bulls should stop trying to get the government to rescue the market. Every market rescue simply creates a new batch of trapped investors. The bulls must die before the decline can stop -- must such a simple stock market principle really be spelled out?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/normalfall.md","sourceDirName":"qiangguo","slug":"/qiangguo/normalfall","permalink":"/en/qiangguo/normalfall","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"normalfall","title":"","hide_table_of_contents":true,"sidebar_label":"The Current Stock Market Decline Is Just Normal Market Behavior; The Bulls\' Final Wail, Attempting to Create Public Opinion to Blackmail the Government \u2014 What Exactly Are Their Intentions? (2004-9-10)"},"sidebar":"qiangguoSidebar","previous":{"title":"Speculation Must Be Vindicated \u2014 China\'s Rise Also Needs Its Own Soros and Quantum Fund (2004-9-15)","permalink":"/en/qiangguo/justifyspeculation"},"next":{"title":"\u201C\u65B0\u5DE6\u6D3E\u201D\u4F01\u56FE\u5229\u7528\u80A1\u6743\u5206\u7F6E\u95EE\u9898\u7684\u89E3\u51B3\u8981\u631F\u653F\u5E9C\u800C\u4F01\u56FE\u8FBE\u5230\u4E0D\u53EF\u544A\u4EBA\u76EE\u7684\u90FD\u662F\u75F4\u5FC3\u5984\u60F3","permalink":"/en/qiangguo/wishfulthinking"}}'),r=n(74848),o=n(28453);let s={id:"normalfall",title:"",hide_table_of_contents:!0,sidebar_label:"The Current Stock Market Decline Is Just Normal Market Behavior; The Bulls' Final Wail, Attempting to Create Public Opinion to Blackmail the Government \u2014 What Exactly Are Their Intentions? (2004-9-10)"},i="The Stock Market's Current Decline Is Just Normal Market Law -- The Bulls' Last Wailing, Their Attempt to Manufacture Public Opinion to Coerce the Government: What Are Their True Intentions? (2004-9-10)",l={},u=[];function c(e){let t={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"the-stock-markets-current-decline-is-just-normal-market-law----the-bulls-last-wailing-their-attempt-to-manufacture-public-opinion-to-coerce-the-government-what-are-their-true-intentions-2004-9-10",children:"The Stock Market's Current Decline Is Just Normal Market Law -- The Bulls' Last Wailing, Their Attempt to Manufacture Public Opinion to Coerce the Government: What Are Their True Intentions? (2004-9-10)"})}),"\n",(0,r.jsx)(t.p,{children:"As soon as I came online today, I found an unusually large number of posts about the stock market. Yesterday this young lady already wrote: \"1300 Points Lost -- Hot Commentary: Respecting the Market Is the Basic Quality of Every Regulator. Let Us Warmly Applaud the Resounding Slap the Market Has Given to the Stock Market Regulators.\" The stock market's current decline is just normal market law, yet today's sudden surge of stock market posts is like the bulls' last wailing -- an attempt to manufacture public opinion to coerce the government. What are their true intentions? The bulls should stop trying to get the government to rescue the market. Every market rescue simply creates a new batch of trapped investors. The bulls must die before the decline can stop -- must such a simple stock market principle really be spelled out?"}),"\n",(0,r.jsx)(t.p,{children:"The current so-called bulls, apart from ordinary retail investors, are mostly institutional investors. Haven't the legions of incompetent analysts you feed even figured out something as simple as: \"The major correction that began in 2001 is a large-scale correction of the great bull market that started in 1987. It is perfectly normal for a 13-14 year bull market to be corrected over 5 to 7 years. It's only been 3 years so far -- there's a long way to go.\" How many people in the securities industry today are just there for a free meal? For over a decade, every time the market turns bad, they pressure the government into rescuing it. Meanwhile, institutional problems pile up one after another. Is this really all because of market problems? Do they themselves have no problems? The bulls' wailing is nothing but an attempt to cover up their own problems. Once the market improves, the institutional bosses' positions are safe again? The market is meant to eliminate the unfit. Incompetents don't deserve to exist in the capital markets."}),"\n",(0,r.jsx)(t.p,{children:"The US stock market fell from over 5000 to around 1000 in 2001 -- did anything catastrophic happen? In 1993, our market fell from 1558 to 325 -- did anything catastrophic happen? Stop endlessly catastrophizing every stock market decline. Market corrections are not subject to anyone's will. Using the stock market to stir up public sentiment to coerce the government in order to cover up one's own mistakes -- that is the bulls' sole objective. Nobody forced you to be a bull. In a bear market, bullishness is a graveyard -- does such a simple principle really need explanation?"}),"\n",(0,r.jsx)(t.p,{children:"We must be strictly vigilant against the bulls, especially bullish institutional players, using market sentiment to achieve their sinister objectives. Those who incite market sentiment to coerce the government must be severely punished."})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>i});var a=n(96540);let r={},o=a.createContext(r);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);